#include "../Source/PluginProcessor.h"
#include <iostream>
#include <stdexcept>
int runInstalledBankSmoke(const juce::File& catalogue){try{
 const auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};const auto design=juce::JSON::parse(catalogue);require(int(design["active_presets"])==300,"Missing installed-bank catalogue");
 const auto directory=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("InfinityInstalled094",{},false);auto p=std::make_unique<SpaceInfinityProcessor>(directory,true);
 require(p->bundledPresetError.isEmpty(),"Automatic constructor bank provision failed");auto& bank=p->presetBank();require(bank.entries().size()==301,"Fresh installation lacks the complete curated bank");
 for(const auto& name:juce::StringArray{"SPACE_INFINITY_Heritage_200.zip","SPACE_INFINITY_Lush_Trance_20.zip","SPACE_INFINITY_Orbit_Voices.zip"}){const auto marker=directory.getChildFile("bundled_"+name.replaceCharacter('.','_')+".sha256");require(marker.loadFileAsString().trim()==design["banks"][juce::Identifier(name)]["sha256"].toString(),"Embedded bank differs from calibrated catalogue");}
 juce::StringArray keys;int sampled=0;for(size_t i=0;i<bank.entries().size();++i){const auto entry=bank.entries()[i];require(!keys.contains(entry.key),"Duplicate installed preset");keys.add(entry.key);if(entry.factory==0)continue;require(p->loadBankPreset(int(i)).wasOk(),"Installed preset does not load");const auto settings=design["settings"][juce::Identifier(entry.key)];require(settings.isObject(),"Unexpected preset or missing calibration");require(entry.tags.contains("Level Matched 094")&&entry.tags.contains("Curated 300"),"Installed preset missing its current revision tag");for(const auto& value:settings.getDynamicObject()->getProperties()){const auto* parameter=p->state.getRawParameterValue(value.name.toString());require(parameter&&std::abs(parameter->load()-float(value.value))<.0001f,"Installed preset parameters differ from calibrated data");}
  if(entry.key.startsWith("Uuser_orbitvoices093_")){++sampled;require(p->state.state.getProperty("sampleName").toString().startsWith("Infinity_"),"Sampled preset has no renamed embedded source");require(p->state.getRawParameterValue("sampleStereo")->load()==1,"Sampled preset lost stereo fidelity");}
 }
 require(sampled==int(design["sampled_presets"]),"New sampled presets missing from automatic installation");require(p->ensureBundledPresets().wasOk()&&bank.entries().size()==301,"Repeated startup duplicates or resurrects bank entries");
 // Reinstallation must preserve a real user sound replacement and metadata edit.
 juce::String key;for(const auto& e:bank.entries())if(e.key.startsWith("Uuser_orbitvoices093_")){key=e.key;break;}int index=bank.indexForKey(key);require(index>=0,"Editable sample fixture missing");require(p->loadBankPreset(index).wasOk(),"Editable fixture load");auto* gain=p->state.getParameter("presetReferenceGain");gain->setValueNotifyingHost(gain->convertTo0to1(-17));require(p->replaceBankPreset(index).wasOk(),"User replacement failed");require(bank.updateDetails(index,"Owner custom lead","Owner","Personal").wasOk(),"User metadata edit failed");require(p->ensureBundledPresets().wasOk(),"Reinstall failed");index=bank.indexForKey(key);require(bank.entries()[size_t(index)].name=="Owner custom lead"&&p->loadBankPreset(index).wasOk()&&p->state.getRawParameterValue("presetReferenceGain")->load()==-17,"Reinstall overwrites user changes");

 // Recovery is optional; it must load all removed alternatives under new keys.
 int recovered=0;require(bank.importBank(catalogue.getSiblingFile("SPACE_INFINITY_Curated_300_Alternatives.zip"),recovered).wasOk()&&recovered==121&&bank.entries().size()==422,"Optional alternatives recovery failed");int alternatives=0;for(size_t i=0;i<bank.entries().size();++i)if(bank.entries()[i].key.startsWith("Uuser_curated300alternatives_")){++alternatives;require(bank.entries()[i].tags.contains("Recovered Alternative")&&p->loadBankPreset(int(i)).wasOk(),"Recovered alternative cannot load or lacks its tag");}require(alternatives==121,"Recovery contains missing or duplicate alternatives");
 // An old library upgrades to the curated list without hiding a personal edit
 // of a retired factory sound. Untouched retired slots remain excluded on reload.
 const auto previous=directory.getChildFile("Old library");auto old=std::make_unique<SpaceInfinityProcessor>(previous);require(old->ensureBundledPresets().wasOk(),"Old library setup");const auto curation=juce::JSON::parse(catalogue.getSiblingFile("Curation093.json"));juce::String retiredKey;for(const auto& r:*curation["retired"].getArray())if(r["key"].toString().startsWith("F")){retiredKey=r["key"].toString();break;}auto& oldBank=old->presetBank();const int retiredIndex=oldBank.indexForKey(retiredKey);require(retiredIndex>=0&&old->loadBankPreset(retiredIndex).wasOk(),"Retired editable slot fixture");auto* cutoff=old->state.getParameter("cutoff");cutoff->setValueNotifyingHost(cutoff->convertTo0to1(1234));require(old->replaceBankPreset(retiredIndex).wasOk(),"Owner retired-slot replacement");old.reset();old=std::make_unique<SpaceInfinityProcessor>(previous,true);require(old->presetBank().entries().size()==302,"Upgrade either revived a retired slot or lost the owner replacement");const int preserved=old->presetBank().indexForKey(retiredKey);require(preserved>=0&&old->loadBankPreset(preserved).wasOk()&&std::abs(old->state.getRawParameterValue("cutoff")->load()-1234)<.01f,"Curation overwrote an owner replacement");require(old->ensureBundledPresets().wasOk()&&old->presetBank().entries().size()==302,"Reload changed curated upgrade count");old.reset();
 p.reset();directory.deleteRecursively();std::cout<<"Fresh automatic bank: 300 curated presets + Init; embedded sample presets, bank hashes, repeat startup and user replacements verified\n";return 0;
}catch(const std::exception& e){std::cerr<<"Installed bank: "<<e.what()<<std::endl;return 94;}}
